window.lexProducts=products;
const CART_KEY='lexMarketCart', WISH_KEY='lexMarketWishlist', ORDER_KEY='lexMarketOrders', USER_KEY='lexMarketUser';
const money=n=>'₦'+Number(n).toLocaleString('en-NG');
const get=(key,fallback=[])=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch(e){return fallback}};
const cart=()=>get(CART_KEY,[]); const wish=()=>get(WISH_KEY,[]); const orders=()=>get(ORDER_KEY,[]);
const saveCart=c=>{localStorage.setItem(CART_KEY,JSON.stringify(c));updateCounts()};
const enrich={1:{description:'Titanium design, powerful performance and a pro camera system.',stock:18},2:{description:'Premium Android flagship with an advanced camera and bright display.',stock:24},3:{description:'Wireless earbuds with clear sound, comfortable fit and long battery life.',stock:42},4:{description:'Reliable everyday laptop for school, work and entertainment.',stock:12},5:{description:'Next-generation gaming console with immersive graphics and fast loading.',stock:9},6:{description:'Premium wireless earbuds with active noise cancellation.',stock:21},7:{description:'Affordable everyday laptop for students, work and home use.',stock:16},8:{description:'Responsive wireless controller for console and PC gaming.',stock:30}};
products.forEach(p=>Object.assign(p,enrich[p.id]||{}));
function updateCounts(){const c=cart().reduce((s,x)=>s+Number(x.quantity||0),0);document.querySelectorAll('.cart-link').forEach(link=>{let b=link.querySelector('.cart-badge');if(!b){b=document.createElement('span');b.className='cart-badge';link.appendChild(b)}b.textContent=c;b.classList.toggle('empty',c===0)})}
function inWish(id){return wish().some(x=>x.id===Number(id))}
function toggleWishlist(id){id=Number(id);const p=products.find(x=>x.id===id);if(!p)return;let w=wish();const i=w.findIndex(x=>x.id===id);i>=0?w.splice(i,1):w.push({...p});localStorage.setItem(WISH_KEY,JSON.stringify(w));renderAll();showToast(i>=0?'Removed from wishlist':'Added to wishlist')}
function addToCart(id,qty=1){id=Number(id);qty=Math.max(1,Number(qty)||1);const p=products.find(x=>x.id===id);if(!p)return;let c=cart(),item=c.find(x=>x.id===id);if(item){item.quantity+=qty;if(!item.sellerId&&p.sellerId)item.sellerId=p.sellerId;if(!item.sellerName&&p.sellerName)item.sellerName=p.sellerName;if(!item.firestoreId&&p.firestoreId)item.firestoreId=p.firestoreId;}else c.push({id:p.id,name:p.name,price:p.price,image:p.image,quantity:qty,sellerId:p.sellerId||'',sellerName:p.sellerName||'LEX Seller',firestoreId:p.firestoreId||''});saveCart(c);updateCounts();if(document.getElementById('cartContainer'))renderCart();showToast(p.name+' added to cart')}
function removeFromCart(id){saveCart(cart().filter(x=>x.id!==Number(id)));renderCart();showToast('Item removed')}
function changeQty(id,delta){id=Number(id);let c=cart(),i=c.findIndex(x=>x.id===id);if(i<0)return;c[i].quantity+=delta;if(c[i].quantity<=0)c.splice(i,1);saveCart(c);renderCart()}
function imageTag(p,cls='product-image'){return `<div class="product-photo"><img class="${cls}" src="${p.image}" alt="${p.name}" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.add('image-missing')"></div>`}
function productCard(p,variant=''){return `<article class="card ${variant}"><div class="pic" onclick="openProduct(${p.id})"><span class="discount">${p.discount}% OFF</span><button class="heart ${inWish(p.id)?'saved':''}" onclick="event.stopPropagation();toggleWishlist(${p.id})">${inWish(p.id)?'♥':'♡'}</button>${imageTag(p)}</div><div class="card-body"><small>${p.category}</small><h3 onclick="openProduct(${p.id})">${p.name}</h3><div class="rating">★ ${p.rating} <small>(${p.reviews})</small></div><div class="price"><strong>${money(p.price)}</strong><del>${money(p.oldPrice)}</del></div><button class="add" onclick="addToCart(${p.id})">Add to Cart</button></div></article>`}
function openProduct(id){location.href='product.html?id='+id}
let currentCategory='All',currentSearch='';
function renderProducts(){const b=document.getElementById('productsContainer');if(!b)return;let list=products.filter(p=>(currentCategory==='All'||p.category===currentCategory)&&p.name.toLowerCase().includes(currentSearch.toLowerCase()));b.innerHTML=list.map(productCard).join('');document.getElementById('noProducts')?.classList.toggle('hidden',list.length>0);const rc=document.getElementById('resultCount');if(rc)rc.textContent=list.length+' products'}
function renderHome(){const b=document.getElementById('homeProducts');if(b)b.innerHTML=products.slice(0,4).map(p=>productCard(p,'deal-card')).join('');const f=document.getElementById('featuredProducts');if(f)f.innerHTML=products.slice(4,8).map(p=>productCard(p,'featured-card')).join('')}
function renderDeals(){const b=document.getElementById('dealsContainer');if(b)b.innerHTML=products.slice().sort((a,b)=>b.discount-a.discount).map(productCard).join('')}
function renderWishlist(){const b=document.getElementById('wishlistContainer');if(!b)return;const w=wish();b.innerHTML=w.length?`<div class="wish-list">${w.map(item=>{const p=products.find(x=>x.id===Number(item.id))||item;return `<div class="wish-item"><div class="wish-img">${imageTag(p,'small-product-image')}</div><div><small>${p.category}</small><h3 onclick="openProduct(${p.id})">${p.name}</h3><strong>${money(p.price)}</strong></div><div class="wish-actions"><button class="add" onclick="addToCart(${p.id})">Add to Cart</button><button class="remove" onclick="toggleWishlist(${p.id})">Remove</button></div></div>`}).join('')}</div>`:`<div class="empty"><div>♡</div><h2>Your Wishlist is Empty</h2><p>Save products you love and find them here later.</p><a class="btn primary" href="products.html">Browse Products</a></div>`}
function renderCart(){const b=document.getElementById('cartContainer');if(!b)return;const c=cart();if(!c.length){b.innerHTML=`<div class="empty"><div>🛒</div><h2>Your Cart is Empty</h2><p>Add some products to your cart to get started.</p><a class="btn primary" href="products.html">Start Shopping</a></div>`;return}let sub=0;b.innerHTML=`<div class="cart-layout"><div class="cart-list">${c.map(x=>{const p=products.find(y=>y.id===Number(x.id))||x,total=p.price*x.quantity;sub+=total;return `<div class="cart-item"><div class="cart-img">${imageTag(p,'small-product-image')}</div><div class="cart-info"><h3>${p.name}</h3><strong>${money(p.price)}</strong></div><div class="cart-side"><div class="qty"><button onclick="changeQty(${p.id},-1)">−</button><b>${x.quantity}</b><button onclick="changeQty(${p.id},1)">+</button></div><strong>${money(total)}</strong><button class="remove" onclick="removeFromCart(${p.id})">Remove</button></div></div>`}).join('')}</div><aside class="summary"><h2>Order Summary</h2><div><span>Subtotal</span><strong>${money(sub)}</strong></div><div><span>Delivery</span><strong>₦2,500</strong></div><div class="total"><span>Total</span><strong>${money(sub+2500)}</strong></div><a class="btn primary" href="checkout.html">Proceed to Checkout</a><a class="continue-shopping" href="products.html">Continue Shopping</a></aside></div>`}
function renderCheckout(){const b=document.getElementById('checkoutContainer');if(!b)return;const c=cart();if(!c.length){b.innerHTML=`<div class="empty"><div>🛒</div><h2>Your Cart is Empty</h2><a class="btn primary" href="products.html">Browse Products</a></div>`;return}let sub=c.reduce((sum,x)=>sum+Number(x.price||0)*Number(x.quantity||1),0),fee=2500,total=sub+fee;const summary=b.querySelector('#checkoutSummary');if(summary)summary.innerHTML=`<div><span>Subtotal</span><strong>${money(sub)}</strong></div><div><span>Delivery</span><strong>${money(fee)}</strong></div><div class="total"><span>Total</span><strong>${money(total)}</strong></div>`;const method=b.querySelector('#paymentMethod');const help=b.querySelector('#paymentHelp');if(method&&help){const sync=()=>{help.textContent=method.value==='Paystack'?'Secure checkout opens when you place the order. Your card/bank details are handled by Paystack.':'You will pay when your order is delivered.'};method.onchange=sync;sync()}}
