function escapeReviewText(value){
  return String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
}

async function loadProductReviews(productId,p){
  const list=document.getElementById('reviewList'), summary=document.getElementById('reviewSummary'), badge=document.getElementById('reviewsCountBadge');
  if(!list)return;
  let reviews=[];
  try{ const m=await import('./firebase-data.js?reviews='+Date.now()); reviews=await m.getProductReviews(productId); }
  catch(e){ console.warn('Review load failed:',e); list.innerHTML='<div class="review-empty">Reviews could not be loaded right now.</div>'; return; }
  const avg=reviews.length ? reviews.reduce((sum,r)=>sum+Number(r.rating||0),0)/reviews.length : Number(p.rating||0);
  const displayAvg=reviews.length ? avg.toFixed(1) : Number(p.rating||0).toFixed(1);
  summary.innerHTML=`<strong>★ ${displayAvg}</strong><span>${reviews.length ? `Based on ${reviews.length} customer review${reviews.length===1?'':'s'}` : `No customer reviews yet · Store rating ${Number(p.rating||0).toFixed(1)}`}</span>`;
  badge.textContent=`${reviews.length} review${reviews.length===1?'':'s'}`;
  list.innerHTML=reviews.length ? reviews.map(r=>`<article class="review"><div class="review-top"><b>${escapeReviewText(r.customerName||'LEX Customer')}</b><span class="review-stars">${'★'.repeat(Math.max(1,Math.min(5,Number(r.rating)||1)))}${'☆'.repeat(5-Math.max(1,Math.min(5,Number(r.rating)||1)))}</span></div><span>${escapeReviewText(r.comment)}</span><small>${r.verifiedPurchase?'✓ Verified purchase · ':''}${new Date(r.createdAt).toLocaleDateString()}</small></article>`).join('') : '<div class="review-empty">No customer reviews yet. Be the first verified buyer to share your experience.</div>';
  await setupReviewForm(productId,p,reviews);
}

async function setupReviewForm(productId,p,reviews){
  const form=document.getElementById('reviewForm'), hint=document.getElementById('reviewOrderHint'), btn=document.getElementById('submitReviewBtn');
  if(!form||!hint||!btn)return;
  const user=window.lexFirebase?.user;
  if(!user){ hint.innerHTML='🔐 <a href="auth.html">Sign in</a> to write a verified review after delivery.'; btn.disabled=true; return; }
  let eligible=null;
  try{
    const m=await import('./firebase-data.js?revieworders='+Date.now());
    const mine=await m.getMyOrders();
    eligible=(mine||[]).find(o=>o.status==='Delivered' && (o.items||[]).some(item=>String(item.id ?? item.productId)===String(productId)));
    const already=(reviews||[]).some(r=>r.customerId===user.uid && String(r.orderId)===String(eligible?.orderId));
    if(eligible && already){hint.textContent='✓ You already reviewed this delivered purchase.';btn.disabled=true;return;}
    if(eligible){hint.textContent=`✓ Verified purchase found — order ${eligible.orderId}.`;}
    else{hint.textContent='ℹ️ You need a delivered order containing this product before submitting a review.';btn.disabled=true;return;}
  }catch(e){console.warn('Review eligibility failed:',e);hint.textContent='Could not check your delivered orders. Please try again.';btn.disabled=true;return;}
  form.onsubmit=async ev=>{ev.preventDefault(); if(!eligible)return; btn.disabled=true; btn.textContent='Submitting…';
    try{const m=await import('./firebase-data.js?reviewwrite='+Date.now()); await m.createProductReview(productId,p.name,document.getElementById('reviewRating').value,document.getElementById('reviewComment').value,eligible.orderId); showToast('Review submitted successfully'); await loadProductReviews(productId,p);}
    catch(e){showToast(e.message||'Could not submit review');btn.disabled=false;btn.textContent='Submit Review';}
  };
}

function adjustDetailQty(delta){
  const input=document.getElementById('detailQty');
  if(!input)return;
  input.value=Math.max(1,Math.min(10,Number(input.value||1)+delta));
}

async function renderAccount(){const b=document.getElementById('accountContainer');if(!b)return;const fb=window.lexFirebase?.user;const profile=window.lexFirebase?.profile;const localUser=get(USER_KEY,null);if(!fb){b.innerHTML=`<div class="account-grid"><div class="account-card"><div class="avatar">👤</div><h2>Welcome to LEX Market</h2><p>Sign in to access your account and sync your orders online.</p><div class="account-actions"><a class="btn primary" href="auth.html">Sign In / Create Account</a><a class="btn secondary dark-outline" href="products.html">Continue Shopping</a></div><small class="account-status muted">Guest mode</small></div><div class="account-card"><h2>My Orders</h2><p>Sign in to see your online order history.</p></div></div>`;return}let cloud=[];try{const m=await import('./firebase-data.js');cloud=await m.getMyOrders()}catch(e){console.warn(e)}const name=profile?.name||fb.displayName||'LEX Customer',email=fb.email||'',phone=profile?.phone||'';const local=orders();const merged=[...cloud];for(const o of local){if(!merged.some(x=>x.orderId===o.id))merged.push({...o,orderId:o.id})}b.innerHTML=`<div class="account-grid"><div class="account-card"><div class="avatar">👤</div><h2>${name}</h2><p>${email}</p>${phone?`<p>${phone}</p>`:''}<form id="profileForm" class="profile-form"><label>Full Name<input id="profileName" value="${name.replace(/"/g,'&quot;')}" required></label><label>Phone<input id="profilePhone" value="${phone.replace(/"/g,'&quot;')}" inputmode="tel"></label><button class="btn secondary dark-outline" type="submit">Save Profile</button></form><div class="account-actions"><a class="btn primary" href="products.html">Continue Shopping</a><button class="btn secondary dark-outline" onclick="lexSignOut();location.href='index.html'">Sign Out</button></div><small class="account-status">✓ Firebase account connected</small></div><div class="account-card"><h2>My Orders</h2>${merged.length?merged.slice().sort((a,b)=>new Date(b.date||0)-new Date(a.date||0)).map(x=>`<div class="order-row"><div><b>Order #${x.orderId||x.id}</b><span>${x.status||'Order Placed'}</span></div><a class="btn secondary dark-outline" href="tracking.html?id=${encodeURIComponent(x.orderId||x.id)}">View Details</a></div>`).join(''):'<p>No orders yet. Your orders will appear here after checkout.</p>'}</div><div class="account-card shopping-tools-card"><span class="eyebrow">LEX MARKET</span><h2>Shopping Tools</h2><p class="muted">Quick access to your shopping features.</p><div class="account-actions shopping-tools-actions"><button class="btn secondary dark-outline" type="button" onclick="window.lexOpenAlerts?.()">🔔 Alerts</button><button class="btn secondary dark-outline" type="button" onclick="window.lexOpenNotifications?.()">🔔 Notifications</button><a class="btn secondary dark-outline" href="compare.html">⇄ Compare</a><a class="btn primary" href="addresses.html">📍 My Addresses</a></div></div></div>`;const form=document.getElementById('profileForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{const m=await import('./firebase-data.js');await m.updateMyProfile(document.getElementById('profileName').value.trim(),document.getElementById('profilePhone').value.trim());window.lexFirebase.profile={...(window.lexFirebase.profile||{}),name:document.getElementById('profileName').value.trim(),phone:document.getElementById('profilePhone').value.trim()};showToast('Profile saved');renderAccount()}catch(err){showToast(err.message||'Could not save profile')}}}
async function renderTracking(){
  const b=document.getElementById('trackingContainer');
  if(!b)return;
  let id=new URLSearchParams(location.search).get('id');
  let o=null;
  const list=orders();
  if(id) o=list.find(x=>String(x.id)===String(id))||null;

  if(window.lexFirebase?.user){
    try{
      const m=await import('./firebase-data.js?tracking='+Date.now());
      if(!id){
        const latest=await m.getMyOrders();
        if(latest?.length){
          latest.sort((a,b)=>new Date(b.date||0)-new Date(a.date||0));
          id=latest[0].orderId;
        }
      }
      if(id){
        const cloud=await m.getMyOrder(id);
        if(cloud)o={
        id:cloud.orderId,
        customer:cloud.customer,
        items:cloud.items,
        total:cloud.total,
        status:cloud.status||'Order Placed',
        date:cloud.date,
        sellerOrders:cloud.sellerOrders||[]
      };
      }
    }catch(e){ console.warn('Tracking load failed:',e); }
  }

  if(!o){
    b.innerHTML='<div class="empty"><div>📦</div><h2>No Order Found</h2><p>We could not find this order in your account.</p><a class="btn primary" href="account.html">My Orders</a></div>';
    return;
  }

  function statusRank(status){
    return {'Order Placed':0,'Processing':1,'Shipped':2,'Out for Delivery':3,'Delivered':4,'Cancelled':-1}[status]??0;
  }

  function draw(currentOrder){
    const steps=['Order Placed','Processing','Shipped','Out for Delivery','Delivered'];
    const current=Math.max(0,steps.indexOf(currentOrder.status));
    const sellerRows=(currentOrder.sellerOrders||[]).map(so=>`<div class="seller-track-row"><div><b>${so.sellerName||'LEX Seller'}</b><small>${(so.items||[]).map(i=>`${i.name} × ${i.quantity}`).join(', ')}</small></div><span>${so.status||'Order Placed'}</span></div>`).join('');
    b.innerHTML=`<div class="tracking-card"><div class="tracking-head"><div><small>ORDER</small><h2>${currentOrder.id}</h2></div><span>${currentOrder.status||'Order Placed'}</span></div><div class="timeline">${steps.map((st,i)=>`<div class="track-step ${i<=current?'done':''}"><b>${i<=current?'✓':i+1}</b><span>${st}</span></div>`).join('')}</div><div class="tracking-info"><p><b>Customer:</b> ${currentOrder.customer?.name||'LEX Customer'}</p><p><b>Delivery:</b> ${currentOrder.customer?.address||''}${currentOrder.customer?.city?', '+currentOrder.customer.city:''}</p><p><b>Placed:</b> ${currentOrder.date?new Date(currentOrder.date).toLocaleString():'Recently'}</p></div>${sellerRows?`<div class="seller-tracking"><h3>Seller Fulfilment</h3>${sellerRows}</div>`:'<div class="seller-tracking"><h3>Seller Fulfilment</h3><p class="muted">Seller fulfilment details will appear here once your order is assigned to a seller.</p></div>'}</div>`;
  }

  draw(o);

  // Replace the old polling approach with a real Firestore listener.
  if(window.lexTrackingUnsubscribe) window.lexTrackingUnsubscribe();
  window.lexTrackingUnsubscribe=null;
  if(window.lexFirebase?.user){
    try{
      const m=await import('./firebase-data.js?live='+Date.now());
      window.lexTrackingUnsubscribe=m.watchMyOrder(id,(sellerRows)=>{
        const next={...o,sellerOrders:sellerRows};
        if(sellerRows.length){
          const statuses=sellerRows.map(x=>x.status||'Order Placed');
          next.status=statuses.reduce((lowest,status)=>statusRank(status)<statusRank(lowest)?status:lowest,statuses[0]);
        }
        o=next;
        draw(o);
      });
    }catch(e){ console.warn('Live tracking setup failed:',e); }
  }
}

function renderSeller(){const b=document.getElementById('sellerContainer');if(!b)return;const saved=get('lexMarketSellerProducts',[]);b.innerHTML=`<div class="dashboard-grid"><div class="stat"><span>Products</span><strong>${saved.length+8}</strong></div><div class="stat"><span>Orders</span><strong>${orders().length}</strong></div><div class="stat"><span>Wishlist Saves</span><strong>${wish().length}</strong></div></div><div class="dashboard-card"><div class="heading compact"><h2>Seller Products</h2><button class="btn primary" onclick="addSellerDemo()">+ Add Product</button></div><div class="seller-table">${saved.length?saved.map((p,i)=>`<div><b>${p.name}</b><span>${money(p.price)}</span><button onclick="removeSellerDemo(${i})">Remove</button></div>`).join(''):'<p>No custom products yet. Add a demo product to test the seller flow.</p>'}</div></div>`}
function addSellerDemo(){const s=get('lexMarketSellerProducts',[]);s.push({name:'New LEX Seller Product',price:75000,stock:10});localStorage.setItem('lexMarketSellerProducts',JSON.stringify(s));renderSeller();showToast('Product added')}
function removeSellerDemo(i){const s=get('lexMarketSellerProducts',[]);s.splice(i,1);localStorage.setItem('lexMarketSellerProducts',JSON.stringify(s));renderSeller()}
function renderAdmin(){const b=document.getElementById('adminContainer');if(!b)return;const o=orders(),sales=o.reduce((s,x)=>s+x.total,0);b.innerHTML=`<div class="dashboard-grid"><div class="stat"><span>Total Products</span><strong>${products.length}</strong></div><div class="stat"><span>Total Orders</span><strong>${o.length}</strong></div><div class="stat"><span>Demo Sales</span><strong>${money(sales)}</strong></div></div><div class="dashboard-card"><h2>Recent Orders</h2>${o.length?o.slice().reverse().map(x=>`<div class="admin-order"><b>${x.id}</b><span>${x.customer.name}</span><strong>${money(x.total)}</strong><select onchange="updateOrderStatus('${x.id}',this.value)">${['Order Placed','Processing','Shipped','Out for Delivery','Delivered'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></div>`).join(''):'<p>No orders yet.</p>'}</div>`}
function updateOrderStatus(id,status){const o=orders(),x=o.find(a=>a.id===id);if(x){x.status=status;localStorage.setItem(ORDER_KEY,JSON.stringify(o));renderAdmin();showToast('Order status updated')}}
function search(){const v=document.getElementById('searchInput')?.value.trim()||'';if(location.pathname.toLowerCase().endsWith('products.html')){currentSearch=v;renderProducts()}else location.href='products.html?search='+encodeURIComponent(v)}
function setup(){
  updateCounts();
  document.getElementById('searchButton')?.addEventListener('click',search);
  document.getElementById('searchInput')?.addEventListener('keydown',e=>{if(e.key==='Enter')search()});
  document.querySelectorAll('.filter').forEach(btn=>btn.addEventListener('click',()=>{
    document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));
    btn.classList.add('active');
    currentCategory=btn.dataset.category;
    renderProducts();
  }));
  const q=new URLSearchParams(location.search);
  if(q.get('search')){currentSearch=q.get('search');const i=document.getElementById('searchInput');if(i)i.value=currentSearch}
  if(q.get('category'))currentCategory=q.get('category');

  renderHome();
  renderProducts();
  renderDeals();
  renderWishlist();
  renderCart();
  renderCheckout();
  renderProduct();
  renderAccount();
  renderTracking();

  // Hidden admin entry: a single tap on the small LEX MARKET label in Settings.
  // The label is intentionally subtle; Firebase still protects the dashboard.
  (()=>{
    const trigger=document.getElementById('secretAdminTrigger');
    if(!trigger) return;
    trigger.style.cursor='pointer';
    trigger.addEventListener('click',e=>{
      e.preventDefault();
      location.href='lx-console-7x3.html';
    });
  })();

  // Seller/Admin have their own Firebase-powered dashboards in their HTML files.
  // Do not let the generic demo renderers overwrite those real dashboards.
  const path=location.pathname.toLowerCase();
  if(!path.endsWith('/seller.html') && !path.endsWith('seller.html')) renderSeller();
  if(!path.endsWith('/lx-console-7x3.html') && !path.endsWith('lx-console-7x3.html')) renderAdmin();

  // Keep the navigation state correct even when a page is reached directly.
  const current=(location.pathname.split('/').pop()||'index.html').toLowerCase();
  document.querySelectorAll('.main-nav a, nav .nav a').forEach(a=>{
    const href=(a.getAttribute('href')||'').split('?')[0].toLowerCase();
    if(href && href===current) a.classList.add('active');
  });
}
function renderAll(){renderHome();renderProducts();renderWishlist();renderProduct();renderAccount();updateCounts()}
function showToast(msg){let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.textContent='✓ '+msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),1800)}
document.addEventListener('DOMContentLoaded',setup);
document.addEventListener('submit',async e=>{
  if(e.target.id!=='checkoutForm')return;
  e.preventDefault();
  const form=e.target;
  const data=Object.fromEntries(new FormData(form).entries()),c=cart();
  if(!c.length)return;
  if(!window.lexFirebase?.user){alert('Please sign in before placing an order.');location.href='auth.html?next=checkout.html';return;}
  const sub=c.reduce((sum,x)=>sum+Number(x.price||0)*Number(x.quantity||1),0),fee=2500,discount=window.lexP7GetCheckoutDiscount?Number(window.lexP7GetCheckoutDiscount()||0):0,total=Math.max(0,sub+fee-discount);
  const orderId='LEX-'+Date.now().toString().slice(-8);
  const paymentMethod=data.payment;
  const btn=document.getElementById('placeOrderBtn');
  if(btn)btn.disabled=true;

  const finishOrder=async(paymentStatus='Pending',paymentReference='')=>{
    const order={id:orderId,customer:{name:data.name,phone:data.phone,email:data.email,address:data.address,city:data.city,state:data.state||'',landmark:data.landmark||'',deliveryNote:data.deliveryNote||''},items:c,total,subtotal:sub,discount,deliveryFee:fee,payment:paymentMethod,paymentStatus,paymentReference,status:'Order Placed',date:new Date().toISOString()};
    const list=orders();list.push(order);
    localStorage.setItem(ORDER_KEY,JSON.stringify(list));
    localStorage.setItem(USER_KEY,JSON.stringify({name:data.name,email:data.email,phone:data.phone}));
    if(window.lexP7Notify) window.lexP7Notify(`Order ${orderId} was placed successfully`,'order');
    localStorage.removeItem('lexMarketCoupon');
    try{
      const m=await import('./firebase-data.js?payment='+Date.now());
      await m.saveOrder(order);
    }catch(err){
      console.error('Firebase order save failed:',err);
      alert('The payment/order could not be saved to your account. Please do not place another order until you confirm the order appears in My Account.');
      if(btn)btn.disabled=false;
      return false;
    }
    localStorage.removeItem(CART_KEY);updateCounts();
    location.href='confirmation.html?id='+encodeURIComponent(order.id);
    return true;
  };

  if(paymentMethod==='Pay on Delivery'){
    await finishOrder('Pending','');
    return;
  }

  const cfg=await import('./payment-config.js?payment='+Date.now());
  if(!cfg.PAYSTACK_PUBLIC_KEY){
    alert('Paystack is not configured yet. Add your Paystack PUBLIC key to payment-config.js, then try again.');
    if(btn)btn.disabled=false;
    return;
  }
  if(typeof PaystackPop==='undefined'){
    alert('Paystack checkout could not load. Check your internet connection and try again.');
    if(btn)btn.disabled=false;
    return;
  }

  try{
    const popup=new PaystackPop();
    popup.newTransaction({
      key:cfg.PAYSTACK_PUBLIC_KEY,
      email:data.email,
      amount:Math.round(total*100),
      currency:cfg.PAYSTACK_CURRENCY,
      channels:cfg.PAYSTACK_CHANNELS,
      firstName:data.name.split(' ')[0]||data.name,
      lastName:data.name.split(' ').slice(1).join(' ')||'',
      phone:data.phone,
      reference:orderId+'-'+Date.now(),
      metadata:{order_id:orderId,customer_name:data.name,phone:data.phone},
      onSuccess:async transaction=>{
        await finishOrder('Paid',transaction.reference||'');
      },
      onCancel:()=>{
        if(btn)btn.disabled=false;
        showToast('Payment cancelled');
      },
      onError:(error)=>{
        console.error('Paystack payment error:',error);
        if(btn)btn.disabled=false;
        alert(error?.message||'Paystack could not complete this payment. Please try again or choose another payment method.');
      },
      onLoad:(response)=>{
        console.log('Paystack checkout loaded:',response);
      }
    });
  }catch(err){
    console.error('Paystack checkout failed:',err);
    alert(err.message||'Could not start Paystack checkout.');
    if(btn)btn.disabled=false;
  }
});
window.addEventListener('lex-auth-changed',()=>{ if(document.getElementById('accountContainer')) renderAccount(); if(document.getElementById('trackingContainer')) renderTracking(); });
window.addEventListener('beforeunload',()=>{ if(window.lexTrackingUnsubscribe) window.lexTrackingUnsubscribe(); });
